		if (fixInfoMap.isEmpty()) {
			return;
		}
		fixShadowFieldAccess(mth, fixInfoMap);
	}

	private enum FieldFixType {
		SUPER,
		CAST
	}

	private static final class FieldFixInfo {
		@Nullable
		private Map<FieldInfo, FieldFixType> fieldFixMap;
	}

	private static Map<String, FieldFixInfo> buildFixInfoMap(List<FieldNode> allFields) {
		Map<String, List<FieldNode>> groupByName = groupByName(allFields);
		if (groupByName.isEmpty()) {
			return Collections.emptyMap();
		}
		Map<String, FieldFixInfo> fixMap = new HashMap<>(groupByName.size());
		for (Map.Entry<String, List<FieldNode>> entry : groupByName.entrySet()) {
			List<FieldNode> fields = entry.getValue();
			if (fields.size() < 2) {
				continue;
			}
			for (FieldNode field : fields) {
				ClassNode declClass = field.getDeclClass();
				if (declClass == null) {
					continue;
				}
				for (FieldNode otherField : fields) {
					if (field == otherField) {
						continue;
					}
					ClassNode otherDeclClass = otherField.getDeclClass();
					if (otherDeclClass == null) {
						continue;
					}
					if (declClass == otherDeclClass) {
						continue;
					}
					if (declClass.isInheritFrom(otherDeclClass)) {
						FieldFixInfo info = fixMap.computeIfAbsent(declClass.getRawName(), k -> new FieldFixInfo());
						if (info.fieldFixMap == null) {
							info.fieldFixMap = new HashMap<>();
						}
						info.fieldFixMap.put(field.getFieldInfo(), FieldFixType.SUPER);
					} else if (otherDeclClass.isInheritFrom(declClass)) {
						FieldFixInfo info = fixMap.computeIfAbsent(otherDeclClass.getRawName(), k -> new FieldFixInfo());
						if (info.fieldFixMap == null) {
							info.fieldFixMap = new HashMap<>();
						}
						info.fieldFixMap.put(otherField.getFieldInfo(), FieldFixType.CAST);
					}
				}
			}
		}
		return fixMap;
	}

	private static Map<String, List<FieldNode>> groupByName(List<FieldNode> allFields) {
		Map<String, List<FieldNode>> groupByName = new HashMap<>(allFields.size());
		for (FieldNode field : allFields) {
			groupByName
					.computeIfAbsent(field.getName(), k -> new ArrayList<>())
					.add(field);
		}
		return groupByName;
	}

	private static List<FieldNode> collectAllInstanceFields(ClassNode cls) {
		List<FieldNode> fieldsList = new ArrayList<>();
		ClassNode currentClass = cls;
		while (currentClass != null) {
			for (FieldNode field : currentClass.getFields()) {
				if (!field.getAccessFlags().isStatic()) {
					fieldsList.add(field);
				}
			}
			ArgType superClass = currentClass.getSuperClass();
			if (superClass == null) {
				break;
			}
			currentClass = cls.root().resolveClass(superClass);
		}
		return fieldsList;
	}

	private static void fixShadowFieldAccess(MethodNode mth, @Nullable Map<String, FieldFixInfo> fixInfoMap) {
		for (BlockNode block : mth.getBasicBlocks()) {
			for (InsnNode insn : block.getInstructions()) {
				processInsn(mth, insn, fixInfoMap);
			}
		}
	}

	private static void processInsn(MethodNode mth, InsnNode insn, @Nullable Map<String, FieldFixInfo> fixInfoMap) {
		if (fixInfoMap == null) {
			return;
		}
		// After the null check, use a non-null local to satisfy NullAway
		Map<String, FieldFixInfo> nonNullFixInfoMap = fixInfoMap;

		FieldInfo fieldInfo = getFieldInfo(insn);
		if (fieldInfo == null) {
			return;
		}
		InsnArg arg = insn.getArg(insn.getArgsCount() - 1);
		ArgType type = arg.getType();
		if (!type.isTypeKnown() || !type.isObject()) {
			return;
		}
		FieldFixInfo fieldFixInfo = nonNullFixInfoMap.get(type.getObject());
		if (fieldFixInfo == null || fieldFixInfo.fieldFixMap == null) {
			return;
		}
		FieldFixType fieldFixType = fieldFixInfo.fieldFixMap.get(fieldInfo);
		if (fieldFixType == null) {
			return;
		}
		fixFieldAccess(mth, fieldInfo, fieldFixType, arg);
	}

	@Nullable
	private static FieldInfo getFieldInfo(InsnNode insn) {
		switch (insn.getType()) {
			case IPUT:
			case IGET:
				return ((FieldInfo) ((IndexInsnNode) insn).getIndex());
			default:
				return null;
		}
	}

	private static void fixFieldAccess(MethodNode mth, FieldInfo fieldInfo, FieldFixType fieldFixType, InsnArg arg) {
		if (fieldFixType == FieldFixType.SUPER) {
			if (arg.isThis()) {
				// convert 'this' to 'super'
				arg.add(AFlag.SUPER);
				return;
			}
		}
		// apply cast
		InsnNode castInsn = new IndexInsnNode(InsnType.CAST, fieldInfo.getDeclClass().getType(), 1);
		castInsn.addArg(arg.duplicate());
		castInsn.add(AFlag.SYNTHETIC);
		castInsn.add(AFlag.EXPLICIT_CAST);
		arg.wrapInstruction(mth, castInsn, false);
	}
}
